H.background();
const w = H.W, h = H.H;
const m = Math.max(0.05, P.m), k = Math.max(0.1, P.k), A = P.A;
const omega = Math.sqrt(k / m);
const T = 2 * Math.PI / omega;
const x = A * Math.cos(omega * t);
const acc = -omega * omega * x;
const Fspring = -k * x;
// geometry: a spring hanging horizontally from a wall on the left
const wallX = 70, eqX = w * 0.5, scale = 70; // px per meter for displacement
const blockX = eqX + x * scale;
const yMid = h * 0.42;
// wall
H.rect(wallX - 14, yMid - 60, 14, 120, { fill: H.colors.panel, stroke: H.colors.axis, width: 1.5 });
// coiled spring from wall to block
const coils = 12, pts = [];
const x0 = wallX, x1 = blockX - 24;
for (let i = 0; i <= coils * 2; i++) {
  const f = i / (coils * 2);
  const px = x0 + (x1 - x0) * f;
  const py = yMid + (i === 0 || i === coils * 2 ? 0 : (i % 2 ? -16 : 16));
  pts.push([px, py]);
}
H.path(pts, { color: H.colors.violet, width: 2.5 });
// equilibrium marker
H.line(eqX, yMid - 70, eqX, yMid + 70, { color: H.colors.grid, width: 1, dash: [5, 5] });
H.text("x = 0", eqX - 16, yMid + 88, { color: H.colors.sub, size: 12 });
// the block
H.rect(blockX - 24, yMid - 24, 48, 48, { fill: H.colors.accent, stroke: H.colors.bg, width: 2, radius: 6 });
// restoring-force arrow on the block
H.arrow(blockX, yMid, blockX + Fspring * scale * 0.5, yMid, { color: H.colors.warn, width: 3, head: 11 });
H.text("F = -k·x", blockX + Fspring * scale * 0.5 + (Fspring < 0 ? -64 : 6), yMid - 12, { color: H.colors.warn, size: 12 });
// mini x(t) trace at the bottom
const v = H.plot2d({ xMin: 0, xMax: 4 * Math.max(T, 0.5), yMin: -1.2 * Math.abs(A) - 0.5, yMax: 1.2 * Math.abs(A) + 0.5, box: { x: 60, y: h - 150, w: w - 120, h: 110 } });
v.grid(); v.axes();
v.fn(tau => A * Math.cos(omega * tau), { color: H.colors.accent2, width: 2.5 });
const tw = t % (4 * Math.max(T, 0.5));
v.dot(tw, A * Math.cos(omega * tw), { r: 5, fill: H.colors.warn });
H.text("Mass-spring oscillator:  T = 2·pi·sqrt(m/k)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("m = " + m.toFixed(2) + " kg   k = " + k.toFixed(1) + " N/m   omega = " + omega.toFixed(2) + " rad/s   T = " + T.toFixed(2) + " s", 24, 52, { color: H.colors.sub, size: 13 });
